        if(c_.alter_id){Bytes primary(c_.uuid.begin(),c_.uuid.end()),authentication=primary;auto selection=MaskRange{1,c_.alter_id}.choose();for(unsigned i=0;i<selection;++i){Bytes material=authentication;append(material,to_bytes("16167dc8-16b6-4e6d-b8bb-65dd68113a81"));auto next=digest("md5",material);while(equal_bytes(next,authentication)){append(material,to_bytes("533eff8a-4113-4b10-b5ce-0f5d76b98cd2"));next=digest("md5",material);}authentication=std::move(next);}Bytes timestamp;be64(timestamp,uint64_t(std::time(nullptr)));auto out=hmac("md5",authentication,timestamp);Bytes time_material;for(unsigned i=0;i<4;++i)append(time_material,timestamp);append(primary,to_bytes("c48619fe-8f02-49e0-b9e9-edf763e17e21"));AesCfb encoder;encoder.start(digest("md5",primary),digest("md5",time_material));append(out,encoder.apply(header));if(body_cipher_=="chacha20-poly1305"){auto a=digest("md5",up_key_);append(a,digest("md5",a));up_key_=std::move(a);}return out;}
        Bytes id(c_.uuid.begin(),c_.uuid.end());append(id,to_bytes("c48619fe-8f02-49e0-b9e9-edf763e17e21"));auto command_key=digest("md5",id);Bytes auth;auto timestamp=uint64_t(std::time(nullptr));for(int i=7;i>=0;--i)auth.push_back(uint8_t(timestamp>>(8*i)));append(auth,random_bytes(4));be32(auth,crc32(auth));auth=aes(first(vmess_kdf(command_key,{to_bytes("AES Auth ID Encryption")}),16),{},auth,{},false,true);auto nonce=random_bytes(8);
