    Bytes encode(const Bytes& plain){if(c_.protocol=="vless")return encryption_.encode(vision_.encode(plain));if(c_.protocol=="trojan"||ss_none_||vmess_zero_)return plain;if(ss_stream_)return up_cfb_.apply(plain);Bytes out;size_t maximum=c_.protocol=="ss"?(ss2022_?65535:16383):16368;for(size_t i=0;i<plain.size();i+=maximum){auto n=std::min(maximum,plain.size()-i);Bytes part(plain.begin()+std::ptrdiff_t(i),plain.begin()+std::ptrdiff_t(i+n));append(out,c_.protocol=="ss"?ss_frame(part):vmess_frame(part));}return out;}
