    if(c.protocol=="vless"){out+="|encryption="+(c.encryption=="none"?c.encryption:c.encryption.substr(0,c.encryption.find('.',c.encryption.find('.')+1)+1)+c.encryption.substr(c.encryption.find('.',c.encryption.find('.')+1)+1,4));}
    out+="|aid="+(c.alter_id?std::string("legacy"):std::string("aead"));out+="|plugin="+c.ss_plugin+"|mux="+(c.ss_plugin_mux?"1":"0");out+="|ed="+(c.ws_early_data?std::string("active"):std::string("off"));out+="|ech="+(c.ech.empty()?std::string("off"):std::string("active"));
    for(const auto& token:{"h3","h2","http/1.1"})if(std::find(c.alpn.begin(),c.alpn.end(),token)!=c.alpn.end())out+="|alpn="+std::string(token);
